#!/usr/bin/env python3
"""
Emergency Dispatch System - Standalone Self-Extractor
Run this file with Python to extract the complete project to your machine:
    python unpack_project.py
"""
import base64
import zipfile
import io
import os
import sys

ZIP_B64 = """"""

def main():
    print('========================================================')
    print('Extracting Emergency Dispatch System (Python + 12 DSA)...')
    print('========================================================')
    zip_bytes = base64.b64decode(ZIP_B64)
    target_dir = os.path.abspath('emergency_dispatch_python')
    os.makedirs(target_dir, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(zip_bytes)) as z:
        z.extractall('.')
    print(f'Successfully unpacked project files!')
    print(f'Project folder: {target_dir}')
    print('')
    print('Quick Start Commands in VS Code:')
    print('  1) cd emergency_dispatch_python')
    print('  2) python main.py         (Interactive CLI with DSA queues)')
    print('  3) python main.py --demo  (Automated 9-step DSA demo)')
    print('  4) python main.py --test  (Run 19/19 passing unit tests)')
    print('  5) python main.py --server(Launch Web Server on http://localhost:8080)')
    print('========================================================')

if __name__ == '__main__':
    main()
